import csv
import io


def _parse_amount(raw):
    if raw is None:
        return None
    text = raw.strip().strip('"').strip()
    if not text:
        return None
    negative = False
    if text.startswith("(") and text.endswith(")"):
        negative = True
        text = text[1:-1].strip()
    text = text.replace("$", "").replace(",", "")
    if text.startswith("-"):
        negative = True
        text = text[1:].strip()
    try:
        value = float(text)
    except ValueError:
        return None
    return -value if negative else value


def summarize_expenses(csv_text):
    totals = {}
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    for parts in rows[1:]:
        if not parts or not any(p.strip() for p in parts):
            continue
        cat = (parts[1] if len(parts) > 1 else "").strip().lower()
        amount = _parse_amount(parts[2] if len(parts) > 2 else "")
        if amount is None or not cat:
            continue
        totals[cat] = totals.get(cat, 0) + amount
    return {k: round(v, 2) for k, v in totals.items()}
